package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import javax.sql.DataSource;import org.springframework.jdbc.core.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.dao.DuplicateKeyException;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import tools.jackson.databind.json.JsonMapper;import io.knowledgebrain.contracts.integration.github.v1.*;
final class GitHubStore {
 record Repository(UUID repositoryId,UUID spaceId,String visibility,String externalId,String fullName,String url,String defaultBranch,String state,long version,UUID connectedBy,String createdAt,String updatedAt,String lastSyncedAt){}
 record Commit(UUID commitId,UUID repositoryId,UUID spaceId,String visibility,String sourceVisibility,String repositoryExternalId,String repositoryFullName,String sha,String subject,String authorLogin,String committedAt,String importedAt,UUID importedBy,String url){}
 record Receipt(UUID syncId,UUID repositoryId,long repositoryVersion,String observedAt,int scannedCount,int importedCount,String headSha,boolean possiblyMore){}
 record Revision(UUID revisionId,long version,UUID actorId,String occurredAt,Repository snapshot){}
 record Page<T>(List<T> items,UUID nextAfter){}
 record SyncPage(List<Receipt> items,Long nextBefore){}
 record Result(Repository repository,boolean replay){}
 record Synced(Repository repository,Receipt sync,boolean replay){}
 private final JdbcTemplate sql;private final TransactionTemplate tx;private final Clock clock;private final UuidV7 ids;private final JsonMapper json=JsonMapper.builder().build();
 GitHubStore(DataSource ds,Clock clock){sql=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));tx.setTimeout(15);this.clock=clock;ids=new UuidV7(clock);}
 private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Repository unavailable");}
 private static ResponseStatusException stale(){return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Repository changed; reload current state");}
 private Repository map(java.sql.ResultSet rs,int n)throws java.sql.SQLException{return new Repository(rs.getObject("repository_id",UUID.class),rs.getObject("space_id",UUID.class),"PRIVATE",rs.getString("external_id"),rs.getString("full_name"),rs.getString("url"),rs.getString("default_branch"),rs.getString("state"),rs.getLong("version"),rs.getObject("connected_by",UUID.class),rs.getTimestamp("created_at").toInstant().toString(),rs.getTimestamp("updated_at").toInstant().toString(),rs.getTimestamp("last_synced_at")==null?null:rs.getTimestamp("last_synced_at").toInstant().toString());}
 Repository get(UUID space,UUID id){var rows=sql.query("SELECT * FROM github_repository WHERE space_id=? AND repository_id=?",this::map,space,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 Result replay(UUID space,UUID actor,String key,String url){var rows=sql.query("SELECT * FROM github_repository WHERE space_id=? AND request_actor=? AND request_key=?",this::map,space,actor,key);if(rows.isEmpty())return null;String hash=sql.queryForObject("SELECT request_hash FROM github_repository WHERE repository_id=?",String.class,rows.getFirst().repositoryId());if(!GitHubRules.hash(url).equals(hash))throw new ResponseStatusException(HttpStatus.CONFLICT,"Creation intent changed");return new Result(rows.getFirst(),true);}
 Result connect(UUID space,UUID actor,String key,String url,GitHubClient.Repository source,String trace){GitHubRules.key(key);if(!GitHubRules.url(source.url()).equals(url))throw GitHubRules.bad();try{return tx.execute(t->{var old=replay(space,actor,key,url);if(old!=null)return old;UUID id=ids.next();Instant at=clock.instant();sql.update("INSERT INTO github_repository(repository_id,space_id,visibility,external_id,full_name,url,default_branch,state,version,connected_by,created_at,updated_at,request_actor,request_key,request_hash) VALUES (?,?,'PRIVATE',?,?,?,?,'ACTIVE',1,?,?,?,?,?,?)",id,space,source.externalId(),source.fullName(),source.url(),source.defaultBranch(),actor,java.sql.Timestamp.from(at),java.sql.Timestamp.from(at),actor,key,GitHubRules.hash(url));var value=get(space,id);revision(value,actor,"GitHubRepositoryConnected",trace);return new Result(value,false);});}catch(DuplicateKeyException e){var old=replay(space,actor,key,url);if(old!=null)return old;throw new ResponseStatusException(HttpStatus.CONFLICT,"This public repository is already connected");}}
 Synced syncReplay(UUID space,UUID id,UUID actor,String key,long expected){var repo=get(space,id);var rows=sql.query("SELECT expected_version,snapshot::text FROM github_sync WHERE repository_id=? AND space_id=? AND actor_id=? AND request_key=?",(rs,n)->{if(rs.getLong(1)!=expected)throw new ResponseStatusException(HttpStatus.CONFLICT,"Sync intent changed");return json.readValue(rs.getString(2),Receipt.class);},id,space,actor,key);return rows.isEmpty()?null:new Synced(repo,rows.getFirst(),true);}
 Synced sync(UUID space,UUID id,UUID actor,String key,long expected,GitHubClient.Batch batch,String trace){GitHubRules.key(key);GitHubRules.version(expected);return tx.execute(t->{get(space,id);sql.queryForObject("SELECT repository_id FROM github_repository WHERE repository_id=? AND space_id=? FOR UPDATE",UUID.class,id,space);var old=syncReplay(space,id,actor,key,expected);if(old!=null)return old;var repo=get(space,id);if(repo.version()!=expected)throw stale();if(!repo.state().equals("ACTIVE"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Repository disconnected");if(!repo.externalId().equals(batch.repository().externalId())||!GitHubRules.url(repo.url()).equals(GitHubRules.url(batch.repository().url()))||batch.commits().size()>20)throw new ResponseStatusException(HttpStatus.CONFLICT,"GitHub repository identity changed");var seen=new HashSet<String>();for(var c:batch.commits())if(!seen.add(c.sha()))throw GitHubRules.bad();Instant at=clock.instant();sql.update("UPDATE github_repository SET full_name=?,url=?,default_branch=?,version=version+1,updated_at=?,last_synced_at=? WHERE repository_id=?",batch.repository().fullName(),batch.repository().url(),batch.repository().defaultBranch(),java.sql.Timestamp.from(at),java.sql.Timestamp.from(at),id);var value=get(space,id);int imported=0;for(var c:batch.commits()){GitHubRules.sha(c.sha());if(sql.queryForObject("SELECT count(*) FROM github_commit WHERE repository_id=? AND sha=?",Integer.class,id,c.sha())>0)continue;UUID commit=ids.next();String uri=value.url()+"/commit/"+c.sha();var entry=new Commit(commit,id,space,"PRIVATE","PUBLIC",value.externalId(),value.fullName(),c.sha(),GitHubRules.text(c.subject(),500,false),c.authorLogin(),Instant.parse(c.committedAt()).toString(),at.toString(),actor,uri);sql.update("INSERT INTO github_commit(commit_id,space_id,repository_id,sha,subject,author_login,committed_at,imported_at,imported_by,snapshot) VALUES (?,?,?,?,?,?,?,?,?,?::jsonb)",commit,space,id,c.sha(),c.subject(),c.authorLogin(),java.sql.Timestamp.from(Instant.parse(c.committedAt())),java.sql.Timestamp.from(at),actor,json.writeValueAsString(entry));var p=GitHubCommitImportedV1.newBuilder().setCommitId(commit.toString()).setRepositoryId(id.toString()).setVersion(1).setVisibility("PRIVATE").setSourceVisibility("PUBLIC").setRepositoryExternalId(value.externalId()).setRepositoryFullName(value.fullName()).setSha(c.sha()).setSubject(c.subject()).setAuthorLogin(c.authorLogin()==null?"":c.authorLogin()).setCommittedAt(entry.committedAt()).setImportedAt(entry.importedAt()).setUrl(uri).build();event(space,commit,actor,"GitHubCommit","github-commit","GitHubCommitImported","github-commit-events",p.toByteArray(),at,trace);imported++;}revision(value,actor,"GitHubRepositorySynchronized",trace);var receipt=new Receipt(ids.next(),id,value.version(),at.toString(),batch.commits().size(),imported,batch.headSha(),batch.possiblyMore());sql.update("INSERT INTO github_sync(sync_id,space_id,repository_id,actor_id,request_key,expected_version,snapshot) VALUES (?,?,?,?,?,?,?::jsonb)",receipt.syncId(),space,id,actor,key,expected,json.writeValueAsString(receipt));return new Synced(value,receipt,false);});}
 Repository disconnect(UUID space,UUID id,UUID actor,long expected,String trace){return tx.execute(t->{get(space,id);sql.queryForObject("SELECT repository_id FROM github_repository WHERE repository_id=? AND space_id=? FOR UPDATE",UUID.class,id,space);var old=get(space,id);if(old.version()!=expected)throw stale();if(old.state().equals("RETIRED"))return old;sql.update("UPDATE github_repository SET state='RETIRED',version=version+1,updated_at=? WHERE repository_id=?",java.sql.Timestamp.from(clock.instant()),id);var value=get(space,id);revision(value,actor,"GitHubRepositoryDisconnected",trace);return value;});}
 Page<Repository> list(UUID space,String state,UUID after,int limit){if(!Set.of("ACTIVE","RETIRED").contains(state)||limit<1||limit>100)throw GitHubRules.bad();var args=new ArrayList<Object>(List.of(space,state));if(after!=null)args.add(after);args.add(limit+1);var rows=sql.query("SELECT * FROM github_repository WHERE space_id=? AND state=?"+(after==null?"":" AND repository_id>?")+" ORDER BY repository_id LIMIT ?",this::map,args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page<>(items,rows.size()>limit?items.getLast().repositoryId():null);}
 Page<Commit> commits(UUID space,UUID repo,UUID after,int limit){get(space,repo);if(limit<1||limit>100)throw GitHubRules.bad();var args=new ArrayList<Object>(List.of(space,repo));if(after!=null)args.add(after);args.add(limit+1);var rows=sql.query("SELECT snapshot::text FROM github_commit WHERE space_id=? AND repository_id=?"+(after==null?"":" AND commit_id>?")+" ORDER BY commit_id LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Commit.class),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page<>(items,rows.size()>limit?items.getLast().commitId():null);}
 Commit commit(UUID space,UUID repo,UUID id){get(space,repo);var rows=sql.query("SELECT snapshot::text FROM github_commit WHERE space_id=? AND repository_id=? AND commit_id=?",(rs,n)->json.readValue(rs.getString(1),Commit.class),space,repo,id);if(rows.isEmpty())throw missing();return rows.getFirst();}
 List<Revision> history(UUID space,UUID repo,long before,int limit){get(space,repo);if(before<1||limit<1||limit>100)throw GitHubRules.bad();return sql.query("SELECT revision_id,version,actor_id,occurred_at,snapshot::text FROM github_repository_revision WHERE repository_id=? AND version<? ORDER BY version DESC LIMIT ?",(rs,n)->new Revision(rs.getObject(1,UUID.class),rs.getLong(2),rs.getObject(3,UUID.class),rs.getTimestamp(4).toInstant().toString(),json.readValue(rs.getString(5),Repository.class)),repo,before,limit);}
 // Logical repository versions order receipts even when timestamps are equal.
 SyncPage syncs(UUID space,UUID repo,Long before,int limit){
  get(space,repo);if(before!=null&&before<1||limit<1||limit>100)throw GitHubRules.bad();
  var args=new ArrayList<Object>(List.of(space,repo));if(before!=null)args.add(before-1);args.add(limit+1);
  var rows=sql.query("SELECT snapshot::text FROM github_sync WHERE space_id=? AND repository_id=?"+(before==null?"":" AND expected_version<?")+" ORDER BY expected_version DESC LIMIT ?",(rs,n)->json.readValue(rs.getString(1),Receipt.class),args.toArray());
  var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new SyncPage(items,rows.size()>limit?items.getLast().repositoryVersion():null);
 }
 private void revision(Repository value,UUID actor,String type,String trace){UUID revision=ids.next();Instant at=Instant.parse(value.updatedAt());sql.update("INSERT INTO github_repository_revision(revision_id,repository_id,version,actor_id,occurred_at,snapshot) VALUES (?,?,?,?,?,?::jsonb)",revision,value.repositoryId(),value.version(),actor,java.sql.Timestamp.from(at),json.writeValueAsString(value));var p=GitHubRepositorySnapshotV1.newBuilder().setRepositoryId(value.repositoryId().toString()).setRevisionId(revision.toString()).setVersion(value.version()).setState(value.state()).setVisibility("PRIVATE").setExternalId(value.externalId()).setFullName(value.fullName()).setUrl(value.url()).setDefaultBranch(value.defaultBranch()).setConnectedBy(value.connectedBy().toString()).setCreatedAt(value.createdAt()).setUpdatedAt(value.updatedAt()).setLastSyncedAt(value.lastSyncedAt()==null?"":value.lastSyncedAt()).build();event(value.spaceId(),value.repositoryId(),actor,"GitHubRepository","github-repository",type,"github-repository-events",p.toByteArray(),at,trace);}
 private void event(UUID space,UUID aggregate,UUID actor,String aggregateType,String topic,String type,String artifact,byte[] payload,Instant at,String trace){if(trace==null||!trace.matches("[0-9a-f]{32}")||trace.equals("0".repeat(32)))throw GitHubRules.bad();UUID event=ids.next();var wire=GitHubEventEnvelopeV1.newBuilder().setEventId(event.toString()).setEventType(type).setEventVersion(1).setOccurredAtEpochMillis(at.toEpochMilli()).setProducer("integration-service").setAggregateType(aggregateType).setAggregateId(aggregate.toString()).setSpaceId(space.toString()).setActorId(actor.toString()).setTraceId(trace).setPayload(com.google.protobuf.ByteString.copyFrom(payload)).build().toByteArray();sql.update("INSERT INTO outbox_event(id,aggregatetype,aggregateid,type,occurred_at,trace_id,schema_group,schema_artifact,schema_version,payload) VALUES (?,?,?,?,?,?,'integration',?,'1',?)",event,topic,aggregate,type,java.sql.Timestamp.from(at),trace,artifact,wire);}
}
